#!/usr/bin/env python3
"""Ranked-choice tally. Usage: tally.py INPUT_DIR OUTPUT_FILE"""
import csv
import io
import json
import os
import re
import sys
import unicodedata
from collections import defaultdict

SKIP, PASS, CHOICE, OVER = 0, 1, 2, 3


def nid(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = str(s).casefold()
    out = []
    for ch in s:
        cat = unicodedata.category(ch)
        out.append(ch if (cat.startswith("L") or cat == "Nd") else " ")
    return " ".join("".join(out).split())


def parse_revision(v):
    return int(str(v).strip())


def read_csv_file(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        text = f.read()
    meta = {}
    pos = 0
    n = len(text)
    # leading comment / blank lines
    while pos < n:
        end = text.find("\n", pos)
        if end < 0:
            end = n
        line = text[pos:end].rstrip("\r")
        if line.strip() == "":
            pos = end + 1
            continue
        if line.startswith("#"):
            m = re.match(r"#\s*([^:]*?)\s*:\s*(.*?)\s*$", line)
            if m:
                meta[m.group(1).strip().lower()] = m.group(2)
            pos = end + 1
            continue
        break
    rows = csv.reader(io.StringIO(text[pos:], newline=""))
    header = None
    records = []
    for row in rows:
        if not row or all(c.strip() == "" for c in row):
            continue
        if header is None:
            header = [c.strip() for c in row]
            continue
        d = {}
        for name, val in zip(header, row):
            d[name] = val
        ranks = {}
        for name, val in d.items():
            m = re.fullmatch(r"rank(\d+)", name)
            if m and val.strip() != "":
                r = int(m.group(1))
                marks = ranks.setdefault(r, [])
                for part in val.split("|"):
                    part = part.strip()
                    if part == "":
                        continue
                    if part[:3].lower() == "wi:":
                        marks.append(("wi", part[3:]))
                    else:
                        marks.append(("c", part))
        records.append((d.get("ballot", "").strip(), d.get("contest", "").strip(), ranks))
    return meta, records


def read_jsonl_file(path):
    meta = None
    records = []
    with open(path, encoding="utf-8-sig") as f:
        for line in f:
            if line.strip() == "":
                continue
            obj = json.loads(line)
            if meta is None:
                meta = obj
                continue
            ranks = {}
            for mk in obj.get("marks", []) or []:
                r = int(mk["rank"])
                lst = ranks.setdefault(r, [])
                if mk.get("candidate") is not None:
                    lst.append(("c", str(mk["candidate"]).strip()))
                elif mk.get("write_in") is not None:
                    lst.append(("wi", str(mk["write_in"])))
            records.append((str(obj.get("ballot", "")), obj.get("contest"), ranks))
    return meta or {}, records


def load_batches(indir):
    cvr = os.path.join(indir, "cvr")
    best = {}
    for name in sorted(os.listdir(cvr)):
        path = os.path.join(cvr, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            meta, recs = read_csv_file(path)
        elif name.endswith(".jsonl"):
            meta, recs = read_jsonl_file(path)
        else:
            continue
        batch = str(meta.get("batch", "")).strip()
        rev = parse_revision(meta.get("revision", 1))
        status = str(meta.get("status", "final")).strip().lower()
        if batch not in best or rev > best[batch][0]:
            best[batch] = (rev, status, recs)
    out = []
    for batch in sorted(best):
        rev, status, recs = best[batch]
        if status == "void":
            continue
        out.append(recs)
    return out


def read_ballot(ranks, max_ranks, cmap, wmap, withdrawn):
    """Return tuple of (kind, value) per ranking 1..max_ranks."""
    seen = set()
    res = []
    for r in range(1, max_ranks + 1):
        marks = ranks.get(r, [])
        cands = set()
        for kind, v in marks:
            if kind == "wi":
                c = wmap.get(norm_text(v))
                if c is not None:
                    cands.add(c)
            else:
                c = cmap.get(nid(v))
                if c is not None:
                    cands.add(c)
        if not cands:
            res.append((SKIP, None))
            continue
        cands = {c for c in cands if c not in withdrawn}
        if not cands:
            res.append((PASS, None))
            continue
        left_b = cands
        cands = {c for c in cands if c not in seen}
        seen |= left_b
        if not cands:
            res.append((SKIP, None))
        elif len(cands) == 1:
            res.append((CHOICE, next(iter(cands))))
        else:
            res.append((OVER, None))
    return tuple(res)


def count_ballot(b, continuing):
    prev_skipped = False
    for kind, v in b:
        if kind == SKIP:
            if prev_skipped:
                return None
            prev_skipped = True
            continue
        prev_skipped = False
        if kind == PASS:
            continue
        if kind == OVER:
            return None
        if v in continuing:
            return v
    return None


def tally_contest(contest, records):
    max_ranks = int(contest.get("max_ranks", 0))
    cmap = {}      # normalized id -> canonical key (normalized)
    names = {}     # normalized id -> id as written
    withdrawn = set()
    active = []
    for c in contest.get("candidates", []):
        k = nid(c["id"])
        cmap[k] = k
        names[k] = c["id"]
        if c.get("status", "active") == "withdrawn":
            withdrawn.add(k)
        else:
            active.append(k)
    wmap = {}
    for w in contest.get("write_ins", []):
        k = nid(w["id"])
        cmap[k] = k
        names[k] = w["id"]
        active.append(k)
        for t in [w.get("name", "")] + list(w.get("aliases", []) or []):
            wmap.setdefault(norm_text(t), k)
    lot = {}
    for i, c in enumerate(contest.get("lot_order", [])):
        lot.setdefault(nid(c), i)

    groups = defaultdict(int)
    for ranks in records:
        groups[read_ballot(ranks, max_ranks, cmap, wmap, withdrawn)] += 1
    total = len(records)

    continuing = set(active)
    rounds = []
    history = []  # list of dicts of votes per round
    winner = None
    while True:
        votes = {c: 0 for c in continuing}
        for b, n in groups.items():
            c = count_ballot(b, continuing)
            if c is not None:
                votes[c] += n
        act = sum(votes.values())
        exhausted = total - act
        entry = {"round": len(rounds) + 1,
                 "tallies": {names[c]: v for c, v in votes.items()},
                 "exhausted": exhausted, "eliminated": []}
        rounds.append(entry)
        history.append(votes)
        if act == 0:
            break
        top = max(votes, key=lambda c: votes[c])
        if votes[top] * 2 > act or len(continuing) == 1:
            winner = top
            break
        zeros = [c for c in continuing if votes[c] == 0]
        if zeros:
            elim = zeros
        else:
            m = min(votes.values())
            tied = [c for c in continuing if votes[c] == m]
            for h in range(len(history) - 2, -1, -1):
                if len(tied) == 1:
                    break
                hm = min(history[h][c] for c in tied)
                tied = [c for c in tied if history[h][c] == hm]
            if len(tied) > 1:
                tied.sort(key=lambda c: lot.get(c, -1))
                tied = [tied[-1]]
            elim = tied
        entry["eliminated"] = sorted(names[c] for c in elim)
        continuing -= set(elim)
    return {"contest": contest["id"], "ballots": total,
            "winner": names[winner] if winner is not None else None,
            "rounds": rounds}


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    with open(os.path.join(indir, "election.json"), encoding="utf-8") as f:
        election = json.load(f)
    by_contest = defaultdict(list)
    for recs in load_batches(indir):
        for ballot, cid, ranks in recs:
            by_contest[cid].append(ranks)
    result = {"election": election.get("election"), "contests": []}
    for contest in election.get("contests", []):
        result["contests"].append(tally_contest(contest, by_contest.get(contest["id"], [])))
    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main()
